// Connects the workflow and domain to the page. No business logic here.
import { useMachine } from "@xstate/react";
import { productsNoContractWorkflow } from "../workflow/products-no-contract.workflow.js";
import * as domain from "../domain/products-no-contract.domain.js";
import ProductsNoContractPage from "../page/ProductsNoContractPage.jsx";

export default function ProductsNoContractController() {
  const [state, send] = useMachine(productsNoContractWorkflow);
  const { items, selectedId, error } = state.context;

  return (
    <ProductsNoContractPage
      status={String(state.value)}
      error={error}
      productCount={domain.productCount(items)}
      stockTotal={domain.stockTotal(items)}
      avgPrice={domain.avgPrice(items)}
      rows={domain.toProductsNoContractRows(items)}
      selectedId={selectedId}
      formValues={domain.toFormValues(domain.findProductsNoContract(items, selectedId))}
      onEdit={(id) => send({ type: "EDIT", id })}
      onCancel={() => send({ type: "CANCEL" })}
    />
  );
}
